package com.quizzer.app.data

/**
 * A quiz topic, loaded from one JSON file.
 *
 * [id] is generated by the app (see [TopicIds]) and is also the file name in app storage.
 * Question IDs are `<topicId>-<index in file>`, e.g. `aak-0`.
 */
data class Topic(
    val id: String,
    val title: String,
    val description: String,
    val questions: List<Question>,
) {
    fun withId(newId: String): Topic =
        copy(id = newId, questions = questions.mapIndexed { i, q -> q.copy(id = questionId(newId, i)) })

    companion object {
        fun questionId(topicId: String, index: Int) = "$topicId-$index"
    }
}

/** A question with 2–4 answers, of which at least one is correct. */
data class Question(
    val id: String,
    val text: String,
    val answers: List<Answer>,
    val explanation: String? = null,
) {
    val correctAnswerIndices: Set<Int>
        get() = answers.indices.filter { answers[it].correct }.toSet()
}

data class Answer(
    val text: String,
    val correct: Boolean,
)

enum class QuestionResult {
    /** Exactly the correct answers were selected. */
    CORRECT,

    /** At least one correct answer selected, but not exactly the correct set. */
    PARTIAL,

    /** No correct answer selected. */
    WRONG;

    companion object {
        fun of(question: Question, selected: Set<Int>): QuestionResult {
            val correct = question.correctAnswerIndices
            return when {
                selected == correct -> CORRECT
                selected.any { it in correct } -> PARTIAL
                else -> WRONG
            }
        }
    }
}
